# --- Included from src/cemu/cemu_dynload.asm ---
# --- WiiXLaunch coreinit dynamic-loader import shims (Cemu code-cave only) ---
#
# Same mechanism as cemu_fs.asm / cemu_mem.asm / cemu_logging.asm: the payload
# is a raw codecave blob, never a real RPL, so nothing it calls goes through OS
# import resolution. Cemu's patch assembler DOES resolve `import.<lib>.<Name>`,
# so each entry below is a one-instruction tail call Cemu points at the real
# coreinit export.
#
# WHY THESE THREE EXIST AT ALL, which is the interesting part.
#
# The obvious way to call nsysnet from the cave is a table of
# `import.nsysnet.socket` shims. That is what the old single-mod API server
# did, with a comment telling the user to delete the file if it broke.
#
# It cannot be in BASE, because Cemu fails the ENTIRE graphic pack when a patch
# import does not resolve - and BotW v208 does not import nsysnet (445 imports,
# no socket calls; checked against the RPX). On a setup where nsysnet.rpl is
# not in the process, a static nsysnet import would take down all of WiiXLaunch
# and every mod, with no log and no partial function, because the pack would
# simply never apply.
#
# coreinit's dynamic loader is imported by BotW and by every other title, so
# these three always resolve. Everything nsysnet is looked up through them at
# runtime, and "nsysnet is not available" becomes a value the log names on a
# host that otherwise works normally. See include/wiixlaunch/cemu/cemu_dynload.hpp.
#
# Keep this table in EXACTLY the same order as the CemuDynLoadImport enum in
# that header.
#
# WIIXL_OFFSET_SYMBOL: g_CemuDynLoadShimTableOffset

wiixlaunch_cemu_dynload_shim_table:
  .int wiixlaunch_cemu_dynload_shim_OSDynLoad_Acquire
  .int wiixlaunch_cemu_dynload_shim_OSDynLoad_FindExport
  .int wiixlaunch_cemu_dynload_shim_OSDynLoad_Release

wiixlaunch_cemu_dynload_shim_OSDynLoad_Acquire:
  b import.coreinit.OSDynLoad_Acquire
wiixlaunch_cemu_dynload_shim_OSDynLoad_FindExport:
  b import.coreinit.OSDynLoad_FindExport
wiixlaunch_cemu_dynload_shim_OSDynLoad_Release:
  b import.coreinit.OSDynLoad_Release


# --- Included from src/cemu/cemu_fs.asm ---
# --- WiiXLaunch coreinit filesystem import shims (Cemu code-cave only) ---
#
# Same mechanism as cemu_mem.asm / cemu_time.asm / cemu_logging.asm: the
# payload is a raw codecave blob, never a real RPL module, so nothing it calls
# goes through OS import resolution. Cemu's own patch assembler DOES resolve
# `import.<lib>.<Name>`, so each entry below is a one-instruction tail call
# that Cemu points at the real coreinit export.
#
# Why this is in the BASE framework and not a game module: these are coreinit
# exports present in every Wii U title, reachable with no game-specific address
# - the same argument cemu_mem.asm's header makes for the memory shims. The
# module loader reads .wxlm blobs off the title's filesystem, so FSAddClient /
# FSOpenFile / FSReadFile are load-bearing for base WiiXLaunch itself and
# cannot be behind "did someone vendor wiixlaunch-botw". Contrast
# gx2_imports.asm, which stays in the BotW module: GX2 is a graphics concern
# the base framework has no business assuming.
#
# scripts/deploy.py includes this file into the same codecave as the compiled
# payload and patches g_CemuFsShimTableOffset (see
# include/wiixlaunch/cemu/cemu_fs.hpp) with THIS table's own offset - the line
# below tells deploy.py which C++ global to patch. Keep
# wiixlaunch_cemu_fs_shim_table in EXACTLY the same order as the CemuFsImport
# enum in that header.
#
# WIIXL_OFFSET_SYMBOL: g_CemuFsShimTableOffset

wiixlaunch_cemu_fs_shim_table:
  .int wiixlaunch_cemu_fs_shim_FSAddClient
  .int wiixlaunch_cemu_fs_shim_FSDelClient
  .int wiixlaunch_cemu_fs_shim_FSInitCmdBlock
  .int wiixlaunch_cemu_fs_shim_FSOpenFile
  .int wiixlaunch_cemu_fs_shim_FSGetStatFile
  .int wiixlaunch_cemu_fs_shim_FSReadFile
  .int wiixlaunch_cemu_fs_shim_FSWriteFile
  .int wiixlaunch_cemu_fs_shim_FSCloseFile
  .int wiixlaunch_cemu_fs_shim_FSReadFileWithPos
  .int wiixlaunch_cemu_fs_shim_FSOpenDir
  .int wiixlaunch_cemu_fs_shim_FSReadDir
  .int wiixlaunch_cemu_fs_shim_FSCloseDir

# None of these are variadic, so unlike the OSReport shim they need no
# CR-bit-6 setup; a plain tail call passes the arguments through untouched.

wiixlaunch_cemu_fs_shim_FSAddClient:
  b import.coreinit.FSAddClient
wiixlaunch_cemu_fs_shim_FSDelClient:
  b import.coreinit.FSDelClient
wiixlaunch_cemu_fs_shim_FSInitCmdBlock:
  b import.coreinit.FSInitCmdBlock
wiixlaunch_cemu_fs_shim_FSOpenFile:
  b import.coreinit.FSOpenFile
wiixlaunch_cemu_fs_shim_FSGetStatFile:
  b import.coreinit.FSGetStatFile
wiixlaunch_cemu_fs_shim_FSReadFile:
  b import.coreinit.FSReadFile
wiixlaunch_cemu_fs_shim_FSWriteFile:
  b import.coreinit.FSWriteFile
wiixlaunch_cemu_fs_shim_FSCloseFile:
  b import.coreinit.FSCloseFile
wiixlaunch_cemu_fs_shim_FSReadFileWithPos:
  b import.coreinit.FSReadFileWithPos
wiixlaunch_cemu_fs_shim_FSOpenDir:
  b import.coreinit.FSOpenDir
wiixlaunch_cemu_fs_shim_FSReadDir:
  b import.coreinit.FSReadDir
wiixlaunch_cemu_fs_shim_FSCloseDir:
  b import.coreinit.FSCloseDir


# --- Included from src/cemu/cemu_logging.asm ---
# --- WiiXLaunch coreinit logging import shims (Cemu code-cave only) ---
#
# Same mechanism as cemu_mem.asm / cemu_time.asm: the payload is a raw
# codecave blob, never a real RPL module, so nothing it calls goes through OS
# import resolution. Cemu's own patch assembler DOES resolve
# `import.<lib>.<Name>`, so each entry below is a one-instruction tail call
# that Cemu points at the real coreinit export.
#
# Why this is in the BASE framework and not a game module: OSReport and the
# MEM2-arena allocators are coreinit exports, present in every Wii U title, and
# reaching them needs no game-specific address - exactly the argument
# cemu_mem.asm's header makes for the memory shims. Base WiiXLaunch's own
# logger (include/wiixlaunch/debug_log.hpp) relays through this table, and the
# module loader has to be able to say something when no game module is
# installed at all, so this cannot live behind "did someone vendor
# wiixlaunch-botw". Contrast gx2_imports.asm, which stays in the BotW module:
# GX2 is a graphics concern the base framework has no business assuming.
#
# scripts/deploy.py includes this file into the same codecave as the compiled
# payload, and patches g_CemuLoggingShimTableOffset (see
# include/wiixlaunch/cemu/cemu_logging.hpp) with THIS table's own offset - the
# line below tells deploy.py which C++ global to patch. Keep
# wiixlaunch_cemu_logging_shim_table in EXACTLY the same order as the
# CemuLogImport enum in that header.
#
# WIIXL_OFFSET_SYMBOL: g_CemuLoggingShimTableOffset

wiixlaunch_cemu_logging_shim_table:
  .int wiixlaunch_cemu_logging_shim_OSReport
  .int wiixlaunch_cemu_logging_shim_MEMAllocFromDefaultHeapEx
  .int wiixlaunch_cemu_logging_shim_MEMFreeToDefaultHeap

wiixlaunch_cemu_logging_shim_OSReport:
  # OSReport is variadic - the PowerPC EABI varargs convention requires the
  # CALLER to set CR bit 6 (cr1's eq bit) to indicate whether any FLOATING
  # POINT args were passed through "...": 0 = none. A real, working graphic
  # pack (BreathOfTheWild/Cheats/PreventRandomSpawns/patch_PreventActorSpawns.asm)
  # does exactly this before its own `bl import.coreinit.OSReport` call.
  # GCC devkitPPC's own variadic-call codegen has no reason to know about
  # this Cafe-SDK-specific bit, so calling through our shim from ordinary
  # C++ left it as whatever garbage was already in CR. This did not crash
  # Cemu's OSReport - it just silently produced nothing, which for a while
  # looked like the cause of the "message never shows up" mystery. The real
  # cause turned out to be simpler and unrelated: Cemu's OSReport
  # implementation (WriteCafeConsole, coreinit_Misc.cpp) line-buffers and
  # only flushes to the log on '\n' - the callers always append one now.
  # This CR-bit fix is still correct and still required regardless - keeping
  # it clears real garbage, it just wasn't the whole story.
  crxor 4*cr1+eq, 4*cr1+eq, 4*cr1+eq
  b import.coreinit.OSReport

wiixlaunch_cemu_logging_shim_MEMAllocFromDefaultHeapEx:
  b import.coreinit.OSAllocFromMEM2Arena

wiixlaunch_cemu_logging_shim_MEMFreeToDefaultHeap:
  b import.coreinit.OSFreeToMEM2Arena


# --- Included from src/cemu/cemu_mem.asm ---
# --- WiiXLaunch coreinit memory import shims (Cemu code-cave only) ---
#
# Same mechanism as cemu_time.asm / cemu_logging.asm: the payload is a raw
# codecave blob, never a real RPL module, so nothing it calls goes through OS
# import resolution. Cemu's own patch assembler DOES resolve
# `import.<lib>.<Name>`, so each entry below is a one-instruction tail call
# that Cemu points at the real coreinit export.
#
# Why these four: the payload's built-in heap is the tail of its code cave and
# ends at 0x01C00000, which is under 4 MB shared with every other pack. That is
# not enough for a mod that wants several 1024x1024 font sheets or a large
# render target. coreinit's base heaps are, and they are reachable from any Wii
# U title without a single game-specific address - which is exactly why this
# lives in the base framework and not in a game module.
#
# MEMAllocFromDefaultHeapEx is deliberately NOT used: it is a coreinit DATA
# export (a function pointer a game may replace), so branching to the symbol
# would jump to the pointer's storage rather than through it. The three
# expanded-heap entry points below are real function exports.
#
# scripts/deploy.py includes this file into the same codecave as the compiled
# payload and patches g_CemuMemShimTableOffset (see include/wiixlaunch/mem.hpp)
# with THIS table's own offset - the line below tells deploy.py which C++
# global to patch. Keep wiixlaunch_cemu_mem_shim_table in EXACTLY the same
# order as the CemuMemImport enum in that header.
#
# WIIXL_OFFSET_SYMBOL: g_CemuMemShimTableOffset

wiixlaunch_cemu_mem_shim_table:
  .int wiixlaunch_cemu_mem_shim_MEMGetBaseHeapHandle
  .int wiixlaunch_cemu_mem_shim_MEMAllocFromExpHeapEx
  .int wiixlaunch_cemu_mem_shim_MEMFreeToExpHeap
  .int wiixlaunch_cemu_mem_shim_MEMGetAllocatableSizeForExpHeapEx

# None of these are variadic, so unlike the OSReport shim they need no CR-bit-6
# setup; a plain tail call passes the arguments through untouched.
#
#   MEMGetBaseHeapHandle(MEMBaseHeapType type)          -> MEMHeapHandle
#   MEMAllocFromExpHeapEx(heap, u32 size, s32 align)    -> void*
#   MEMFreeToExpHeap(heap, void* block)                 -> void
#   MEMGetAllocatableSizeForExpHeapEx(heap, s32 align)  -> u32
#
# A NEGATIVE align means "allocate from the end of the heap" in coreinit's
# expanded heaps; the C++ side always passes a positive one.

wiixlaunch_cemu_mem_shim_MEMGetBaseHeapHandle:
  b import.coreinit.MEMGetBaseHeapHandle

wiixlaunch_cemu_mem_shim_MEMAllocFromExpHeapEx:
  b import.coreinit.MEMAllocFromExpHeapEx

wiixlaunch_cemu_mem_shim_MEMFreeToExpHeap:
  b import.coreinit.MEMFreeToExpHeap

wiixlaunch_cemu_mem_shim_MEMGetAllocatableSizeForExpHeapEx:
  b import.coreinit.MEMGetAllocatableSizeForExpHeapEx


# --- Included from src/cemu/cemu_time.asm ---
# --- WiiXLaunch coreinit time import shims (Cemu code-cave only) ---
#
# Same mechanism as cemu_logging.asm / gx2_imports.asm: the payload is a raw
# codecave blob, never a real RPL module, so nothing it calls goes through OS
# import resolution. Cemu's own patch assembler DOES resolve
# `import.<lib>.<Name>`, so each entry below is a one-instruction tail call
# that Cemu points at the real coreinit export.
#
# scripts/deploy.py includes this file into the same codecave as the compiled
# payload and patches g_CemuTimeShimTableOffset (see
# include/wiixlaunch/time.hpp) with THIS table's own offset - the line below
# tells deploy.py which C++ global to patch. Keep
# wiixlaunch_cemu_time_shim_table in EXACTLY the same order as the
# CemuTimeImport enum in that header.
#
# WIIXL_OFFSET_SYMBOL: g_CemuTimeShimTableOffset

wiixlaunch_cemu_time_shim_table:
  .int wiixlaunch_cemu_time_shim_OSGetTime
  .int wiixlaunch_cemu_time_shim_OSTicksToCalendarTime

# Neither import is variadic, so unlike the OSReport shim these need no
# CR-bit-6 setup. A plain tail call passes the arguments through untouched:
# OSTicksToCalendarTime takes the 64-bit OSTime in r3:r4 (PowerPC EABI splits
# a 64-bit argument across an even/odd register pair) and the OSCalendarTime
# out-pointer in r5.
wiixlaunch_cemu_time_shim_OSGetTime:
  b import.coreinit.OSGetTime

wiixlaunch_cemu_time_shim_OSTicksToCalendarTime:
  b import.coreinit.OSTicksToCalendarTime


# --- Included from vendor/wiixlaunch-botw/src/cemu/gx2_imports.asm ---
